                res.append((col, sorted(comp)))
    return res

def norm_shape(cells):
    """Translate a shape's cells so its top-left is at (0,0); sorted tuple."""
    rs = [r for r, c in cells]; cs = [c for r, c in cells]
    return tuple(sorted((r - min(rs), c - min(cs)) for r, c in cells))

def bbox(cells):
    """Bounding box of a set of cells as (rmin, rmax, cmin, cmax)."""
    rs = [r for r, c in cells]; cs = [c for r, c in cells]
    return min(rs), max(rs), min(cs), max(cs)

def contains(outer, inner):
    """True if inner's bounding box lies inside outer's bounding box."""
    a = bbox(outer); b = bbox(inner)
    return a[0] <= b[0] and b[1] <= a[1] and a[2] <= b[2] and b[3] <= a[3]
